DO $$
BEGIN
	IF '${app_env}' = 'dev' THEN
		ON CONFLICT (ip_address) DO NOTHING;

		SELECT
			seed.device_protocol_id,
			seed.device_id,
			cp.id,
			seed.created_at,
			seed.updated_at
		FROM (VALUES
			('b0000000-0000-0000-0000-000000000001'::UUID, 'a0000000-0000-0000-0000-000000000001'::UUID, '2026-04-03T00:00:00Z'::TIMESTAMPTZ, '2026-04-03T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000002'::UUID, 'a0000000-0000-0000-0000-000000000002'::UUID, '2026-04-02T00:00:00Z'::TIMESTAMPTZ, '2026-04-02T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000003'::UUID, 'a0000000-0000-0000-0000-000000000003'::UUID, '2026-04-03T00:00:00Z'::TIMESTAMPTZ, '2026-04-03T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000004'::UUID, 'a0000000-0000-0000-0000-000000000004'::UUID, '2026-04-01T00:00:00Z'::TIMESTAMPTZ, '2026-04-01T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000005'::UUID, 'a0000000-0000-0000-0000-000000000005'::UUID, '2026-04-03T00:00:00Z'::TIMESTAMPTZ, '2026-04-03T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000006'::UUID, 'a0000000-0000-0000-0000-000000000006'::UUID, '2026-03-30T00:00:00Z'::TIMESTAMPTZ, '2026-03-30T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000007'::UUID, 'a0000000-0000-0000-0000-000000000007'::UUID, '2026-04-03T00:00:00Z'::TIMESTAMPTZ, '2026-04-03T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000008'::UUID, 'a0000000-0000-0000-0000-000000000008'::UUID, '2026-03-25T00:00:00Z'::TIMESTAMPTZ, '2026-03-25T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000009'::UUID, 'a0000000-0000-0000-0000-000000000009'::UUID, '2026-04-03T00:00:00Z'::TIMESTAMPTZ, '2026-04-03T00:00:00Z'::TIMESTAMPTZ),
			('b0000000-0000-0000-0000-000000000010'::UUID, 'a0000000-0000-0000-0000-000000000010'::UUID, '2026-04-02T00:00:00Z'::TIMESTAMPTZ, '2026-04-02T00:00:00Z'::TIMESTAMPTZ)
		) AS seed(device_protocol_id, device_id, created_at, updated_at)
		JOIN communication_protocol cp ON cp.code = 'SNMP'
		ON CONFLICT (device_id, protocol_id) DO NOTHING;

		ON CONFLICT (device_protocol_id) DO NOTHING;
	END IF;
END;
$$;